test('frame: bounce off bottom of brick (top hit)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top row, first col
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  state.ball = { x: 125, y: 120, r: 7, vx: 0, vy: UP }; // ball is just hitting the bottom edge

  frame(mockCtx(), state);

  assert.equal(state.ball.vy, Math.abs(state.ball.vy), 'vy should flip to DOWN');
});

test('frame: bounce off top of brick (bottom hit)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  state.ball = { x: 125, y: 93, r: 7, vx: 0, vy: DOWN }; // ball is just hitting the top edge

  frame(mockCtx(), state);

  assert.equal(state.ball.vy, -Math.abs(state.ball.vy), 'vy should flip to UP');
});

test('frame: bounce off right side of brick (left hit)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  state.ball = { x: 157, y: 110, r: 7, vx: LEFT, vy: 0 }; // ball is just hitting the right edge

  frame(mockCtx(), state);

  assert.equal(state.ball.vx, Math.abs(state.ball.vx), 'vx should flip to RIGHT');
});

test('frame: bounce off left side of brick (right hit)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  state.ball = { x: 93, y: 110, r: 7, vx: RIGHT, vy: 0 }; // ball is just hitting the left edge

  frame(mockCtx(), state);

  assert.equal(state.ball.vx, -Math.abs(state.ball.vx), 'vx should flip to LEFT');
});

test('frame: bounce off corner', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
  // ball is hitting bottom-right corner
  state.ball = { x: 157, y: 120, r: 7, vx: RIGHT, vy: UP }; 

  frame(mockCtx(), state);

  assert.ok(state.ball.vx < 0 && state.ball.vy > 0, 'both vx and vy should flip');
});

test('frame: push out of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;
