  frame(mockCtx(), state);

  assert.ok(!collides(state.ball, brick), 'ball should be pushed outside the brick');
});

test('frame: neighbours - bounce exactly once', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1]; // adjacent brick
  b1.x = 100; b1.y = 100; b1.w = 50; b1.h = 20;
  b2.x = 150; b2.y = 100; b2.w = 50; b2.h = 20;

  // ball is on the seam between b1 and b2
  state.ball = { x: 150, y: 120, r: 7, vx: 0, vy: UP };

  frame(mockCtx(), state);

  assert.equal(state.ball.vy, Math.abs(state.ball.vy), 'vy should flip exactly once');
});

test('frame: tunnelling detection', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.x = 100; brick.y = 100; brick.w = 50; brick.h = 20;

