// Resolves a ball-brick collision: flips velocity based on hit face and pushes the ball out.
function resolveBrickCollision(ball, brick) {
  const ballLeft = ball.x - ball.r;
  const ballRight = ball.x + ball.r;
  const ballTop = ball.y - ball.r;
  const ballBottom = ball.y + ball.r;

  const brickLeft = brick.x;
  const brickRight = brick.x + brick.w;
  const brickTop = brick.y;
  const brickBottom = brick.y + brick.h;

  const overlapX = Math.min(ballRight - brickLeft, brickRight - ballLeft);
  const overlapY = Math.min(ballBottom - brickTop, brickBottom - ballBottom);

  if (overlapX < overlapY) {
    // Side hit
    if (ball.x < brick.x + brick.w / 2) {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
    } else {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
    }
  } else if (overlapY < overlapX) {
    // Top/Bottom hit
    if (ball.y < brick.y + brick.h / 2) {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
    } else {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
    }
  } else {
    // Corner hit
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    if (ball.y < brick.y + brick.h / 2) {
      ball.y = brick.y + brick.h + ball.r;
    } else {
      ball.y = brick.y - ball.r;
    }
  }
}

