for (const brick of state.bricks) {
  if (!brick.alive) continue;

  const isColliding = collides(state.ball, brick);
  const isTunnelling = !isColliding && sweepCollides(state.ball, brick);

  if (isColliding || isTunnelling) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (isColliding) {
      resolveBrickCollision(state.ball, brick);
    } else {
      // Tunnelling: resolve based on movement direction
      if (Math.abs(state.ball.vx) > Math.abs(state.ball.vy)) {
        if (state.ball.vx > 0) {
          state.ball.vx = -Math.abs(state.ball.vx);
          state.ball.x = brick.x - ball.r; // This is wrong, need ball.r
        } else {
          state.ball.vx = Math.abs(state.ball.vx);
          state.ball.x = brick.x + brick.w + ball.r;
        }
      } else {
        if (state.ball.vy > 0) {
          state.ball.vy = -Math.abs(state.ball.vy);
          state.ball.y = brick.y - ball.r;
        } else {
          state.ball.vy = Math.abs(state.ball.vy);
          state.ball.y = brick.y + brick.h + ball.r;
        }
      }
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

